#include "host_session.h"
#include <fstream>
#include <iostream>
using namespace mgo2win::host;
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("private fixture path required");std::ifstream in(argv[1],std::ios::binary);auto read=[&](unsigned n){uint32_t v=0;for(unsigned i=0;i<n;++i){int c=in.get();if(c<0)throw std::runtime_error("fixture truncated");v|=uint32_t(c)<<(8*i);}return v;};auto bytes=[&](){auto n=read(2);if(n>2048)throw std::runtime_error("fixture limit");std::vector<uint8_t>b(n);in.read(reinterpret_cast<char*>(b.data()),n);if(!in)throw std::runtime_error("fixture read");return b;};auto localId=read(4),hostId=read(4);auto local=decode_hello(bytes(),localId);Machine machine(local,hostId,{2},0);machine.poll(0);for(unsigned i=0;i<4;++i){machine.receive(bytes(),i*100+50);machine.poll(i*100+50);auto expected=i==0?Stage::connecting:i==1?Stage::profile:i==2?Stage::synchronizing:Stage::joined;if(machine.result().stage!=expected)throw std::runtime_error("retail response admission stage mismatch");}auto roster=machine.result().roster;if(!roster.complete||roster.count()!=3||!roster.slots[0]||roster.slots[0]->character!=hostId||!roster.slots[13]||roster.slots[13]->character!=localId||!roster.slots[4]||roster.slots[4]->instance!=0x04de)throw std::runtime_error("retail roster identity/slot/instance mismatch");auto match=machine.result().match;if(!match.request||match.request->rotation!=Rotation{15,1,2}||match.request->index!=5||match.request->round!=0||match.request->generation!=105||match.phase!=3)throw std::runtime_error("retail selected map/rule/round/generation mismatch");if(in.peek()!=EOF)throw std::runtime_error("fixture trailing bytes");std::cout<<"private retail response replay: handshake/profile/roster/global generation/selected map and rule passed (not a live join)\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
